\begin{ex}%[6H4N1]
\immini[thm]{
Đếm số hình vuông trong hình sau
}{
\begin{tikzpicture}
    % Vẽ lưới 2x2
    \draw[step=1cm] (0, 0) grid (2, 2);

    % Vẽ viền ngoài hình vuông 2x2
    \draw[thick] (0, 0) rectangle (2, 2);

    % Điền các vòng tròn đặc tại các đỉnh
    \fill (0, 0) circle (2pt); % Góc dưới bên trái
    \fill (0, 2) circle (2pt); % Góc trên bên trái
    \fill (2, 0) circle (2pt); % Góc dưới bên phải
    \fill (2, 2) circle (2pt); % Góc trên bên phải

    % Điền các vòng tròn đặc tại các giao điểm bên trong
    \fill (0, 1) circle (2pt);
    \fill (1, 0) circle (2pt);
    \fill (1, 1) circle (2pt);
    \fill (1, 2) circle (2pt);
    \fill (2, 1) circle (2pt);
\end{tikzpicture}
}
\loigiai{
Số hình vuông có cạnh bằng 1 là $4$\\
Số hình vuông có cạnh là 2 bằng $1$\\
Có $5$ hình vuông trong hình
}\end{ex}
